def address_json_to_fields(apps: Any, schema_editor: Any) -> None:
    """Copy every key of the JSON address; nothing is dropped.

    `line2` (floor, c/o…) has no field of its own: it is appended to the street. The region is
    kept as the province text; an Italian one that is not a province code shows up as a
    validation error the next time the vendor is edited.
    """
    Vendor = apps.get_model('vendors', 'Vendor')
    for vendor in Vendor.objects.exclude(registered_address={}):
        address = vendor.registered_address or {}

        def text(key: str) -> str:
            return str(address.get(key) or '').strip()

        lines = [text('line1'), text('line2')]
        vendor.registered_street = ', '.join(line for line in lines if line)
        vendor.registered_postal_code = text('postal_code')
        vendor.registered_city = text('city')
        vendor.registered_province = text('region')
        country = text('country').upper()
        vendor.registered_country = {'EL': 'GR', 'UK': 'GB'}.get(country, country)
        vendor.save(update_fields=[
            'registered_street',
            'registered_postal_code',
            'registered_city',
            'registered_province',
            'registered_country',
        ])


def address_fields_to_json(apps: Any, schema_editor: Any) -> None:
    Vendor = apps.get_model('vendors', 'Vendor')
    for vendor in Vendor.objects.all():
        street = ' '.join(
            part for part in (vendor.registered_street, vendor.registered_street_number) if part
        )
        address = {
            'line1': street,
            'postal_code': vendor.registered_postal_code,
            'city': vendor.registered_city,
            'region': vendor.registered_province,
            'country': vendor.registered_country,
        }
        vendor.registered_address = {key: value for key, value in address.items() if value}
        vendor.save(update_fields=['registered_address'])


